export function roomTypeCardOf(type: RoomType): RoomTypeCard {
  return Object.assign(new RoomTypeCard(), { id: type.id, name: type.name, summary: type.summary, description: type.description, sleeps: type.sleeps, nightlyRate: type.nightlyRate });
}

export function canCancel(stay: Stay): boolean {
  if ((stay.status === StayStatus.Held)) {
    return true;
  }
  return ((stay.status === StayStatus.Confirmed) && isAfter(parseISO(stay.arrival), parseISO(format(addDays(parseISO(new Date().toISOString().slice(0, 10)), (FREE_CANCEL_DAYS - 1)), 'yyyy-MM-dd'))));
}

export async function cardOf(stay: Stay): Promise<StayCard> {
  return Object.assign(new StayCard(), { id: stay.id, code: stay.code, roomTypeName: stay.roomTypeName, roomNumber: stay.roomNumber, guestName: stay.guestName, arrival: stay.arrival, departure: stay.departure, nights: stay.nights, guests: stay.guests, total: stay.total, status: stay.status, holdEnds: (stay.holdUntil ?? stay.createdAt), canCancel: await canCancel(stay) });
}

export async function cardsOf(stays: Stay[]): Promise<StayCard[]> {
  const cards: StayCard[] = [];
  for (const stay of stays) {
    cards.push(await cardOf(stay));
  }
  return cards;
}

export function checkDates(arrival: string, departure: string): void {
  const nights: number = differenceInDays(parseISO(departure), parseISO(arrival));
  if ((((nights < 1) || (nights > 30)) || isBefore(parseISO(arrival), parseISO(new Date().toISOString().slice(0, 10))))) {
    throw new BadDatesError({});
  }
}

/**
 * Standalone version of takenOn for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function takenOn(roomTypeId: string, night: string, em: EntityManager): Promise<number> {
  const overlapping: Stay[] = await (em.getRepository(Stay).getEntityManager() as SqlEntityManager).createQueryBuilder(Stay, 'e_stay').select('*').where('e_stay.room_type_id = ?', [roomTypeId]).andWhere('e_stay.arrival <= ?', [night]).andWhere('e_stay.departure > ?', [night]).andWhere({ status: { $in: [StayStatus.Held, StayStatus.Confirmed, StayStatus.CheckedIn] } }).getResultList();
  let taken: number = 0;
  for (const stay of overlapping) {
    if (((stay.status !== StayStatus.Held) || ((stay.holdUntil ?? new Date()) > new Date()))) {
      taken = (taken + 1);
    }
  }
  return taken;
}

/**
 * Standalone version of leftFor for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function leftFor(type: RoomType, arrival: string, departure: string, em: EntityManager): Promise<number> {
  let left: number = type.inventory;
  let night: string = arrival;
  while (isBefore(parseISO(night), parseISO(departure))) {
    const free: number = (type.inventory - await takenOn(type.id, night, em));
    if ((free < left)) {
      left = free;
    }
    night = format(addDays(parseISO(night), 1), 'yyyy-MM-dd');
  }
  return left;
}

/**
 * Standalone version of ownStay for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function ownStay(id: string, em: EntityManager): Promise<Stay> {
  const stay: Stay | null = (await (em.getRepository(Stay).getEntityManager() as SqlEntityManager).createQueryBuilder(Stay, 'e_stay').select('*').where('e_stay.id = ?', [id]).andWhere('e_stay.guest_id = ?', [(currentUserId() as string)]).limit(1).getResultList())[0] ?? null;
  if ((stay == null)) {
    throw new NoSuchStayError({});
  }
  return stay;
}

/**
 * Standalone version of cancelStay for use outside NestJS DI context
 * (e.g. queue workers, agent tools). Takes the handles of what it reaches last.
 */
export async function cancelStay(stay: Stay, em: EntityManager): Promise<void> {
  const chargeId: string | null = stay.chargeId;
  if ((chargeId != null)) {
    const charge: string = chargeId;
    await new PaymentProviderClient().refundCharge({ chargeId: charge, amount: stay.total, idempotencyKey: `refund-${stay.code}` });
  }
  stay.status = StayStatus.Cancelled;
  stay.holdUntil = null;
  await em.getRepository(Stay).getEntityManager().persistAndFlush(stay);
  await getMqProducer().publishStayCancelled({ code: stay.code, guestEmail: String(stay.guestEmail), roomTypeName: stay.roomTypeName });
}

@Injectable()
export class FunctionsService {
  constructor(
    @InjectRepository(Stay) private readonly stayRepository: EntityRepository<Stay>,
  ) {}

  /**
   * How many of a room type are sold or held on one night. A lapsed hold no longer counts, even if the job has
   *
   * not reached it yet.
   */
async takenOn(roomTypeId: string, night: string): Promise<number> {
    const overlapping: Stay[] = await (this.stayRepository.getEntityManager() as SqlEntityManager).createQueryBuilder(Stay, 'e_stay').select('*').where('e_stay.room_type_id = ?', [roomTypeId]).andWhere('e_stay.arrival <= ?', [night]).andWhere('e_stay.departure > ?', [night]).andWhere({ status: { $in: [StayStatus.Held, StayStatus.Confirmed, StayStatus.CheckedIn] } }).getResultList();
    let taken: number = 0;
    for (const stay of overlapping) {
      if (((stay.status !== StayStatus.Held) || ((stay.holdUntil ?? new Date()) > new Date()))) {
        taken = (taken + 1);
      }
    }
    return taken;
  }

  /**
   * The fewest rooms left on any night of the stay.
   */
async leftFor(type: RoomType, arrival: string, departure: string): Promise<number> {
    let left: number = type.inventory;
    let night: string = arrival;
    while (isBefore(parseISO(night), parseISO(departure))) {
      const free: number = (type.inventory - await this.takenOn(type.id, night));
      if ((free < left)) {
        left = free;
      }
      night = format(addDays(parseISO(night), 1), 'yyyy-MM-dd');
    }
    return left;
  }

async ownStay(id: string): Promise<Stay> {
    const stay: Stay | null = (await (this.stayRepository.getEntityManager() as SqlEntityManager).createQueryBuilder(Stay, 'e_stay').select('*').where('e_stay.id = ?', [id]).andWhere('e_stay.guest_id = ?', [(currentUserId() as string)]).limit(1).getResultList())[0] ?? null;
    if ((stay == null)) {
      throw new NoSuchStayError({});
    }
    return stay;
  }

  /**
   * Money comes back in full, and the room goes back on sale. A held stay was never charged.
   */
async cancelStay(stay: Stay): Promise<void> {
    const chargeId: string | null = stay.chargeId;
    if ((chargeId != null)) {
      const charge: string = chargeId;
      await new PaymentProviderClient().refundCharge({ chargeId: charge, amount: stay.total, idempotencyKey: `refund-${stay.code}` });
    }
    stay.status = StayStatus.Cancelled;
    stay.holdUntil = null;
    await this.stayRepository.getEntityManager().persistAndFlush(stay);
    await getMqProducer().publishStayCancelled({ code: stay.code, guestEmail: String(stay.guestEmail), roomTypeName: stay.roomTypeName });
  }

}
